function getSchoolMajorOutcomes(schoolName) {
  return SCHOOL_MAJOR_OUTCOMES[schoolName] || null;
}

function getMajorOutcome(schoolName, cip4digit) {
  const majors = SCHOOL_MAJOR_OUTCOMES[schoolName];
  if (!majors) return null;
  return majors.find(m => m.cip === cip4digit) || null;
}

if (typeof window !== 'undefined') {
  window.SCHOOL_MAJOR_OUTCOMES = SCHOOL_MAJOR_OUTCOMES;
  window.getSchoolMajorOutcomes = getSchoolMajorOutcomes;
  window.getMajorOutcome = getMajorOutcome;
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { SCHOOL_MAJOR_OUTCOMES, getSchoolMajorOutcomes, getMajorOutcome };
}
